// Material Balance Studio, demo 2: a gas cap, an aquifer and moving
// contacts (the Ekene gas-cap scenario, seed/mbal_companions.mjs: an oil rim
// saturated at 3,200 psia under a gas cap with m = 0.45 and a Carter-Tracy
// edge aquifer, generated by the engine from N = 18.0 MM stb). The run, the
// gas cap and water drive indices, the climbing Campbell plot, the pressure
// history match, and the contacts through time.
import {
  login, expectText, deleteCases, seedCase, setCarterTracy, setContacts, runMbal, showPlot, t, tab,
  GASCAP, GASCAP_FILE,
} from './mbal-common.mjs';

const CASE = 'MBAL demo: Ekene gas-cap scenario';
const seg = (d, name) => d.page.getByRole('radio', { name }).or(d.page.getByRole('button', { name, exact: true })).first();

export default {
  id: 'mbal-02',
  app: 'Material Balance Studio',
  eyebrow: 'Material Balance Studio · 2 of 3',
  title: 'A gas cap, an aquifer and *moving contacts*',
  subtitle: 'Drive indices, the Campbell signature of water, a pressure history match and the contacts through time',
  outroTitle: 'Material balance *with Petrolord*',
  outroSub: 'Material Balance Studio · petrolord.com',
  viewport: { w: 1440, h: 810 },
  async setup(d, shared) {
    d.page.on('dialog', (dg) => dg.accept().catch(() => {}));
    await login(d.page, shared.baseUrl, shared.env);
    await deleteCases(d, shared, /^MBAL demo: Ekene gas-cap scenario$/);
    await seedCase(d, shared, CASE, {
      file: GASCAP_FILE, fluid: 'Oil with gas cap', c: GASCAP.c, pvt: GASCAP.pvt, reservoir: 'Ekene Sand (gas-cap scenario)',
      before: (dd) => setCarterTracy(dd, GASCAP.ct),
    });
    await setContacts(d, GASCAP.contacts);
    await d.click(tab(d, 'Data'));
    await d.sleep(1500);
    await d.page.evaluate(() => window.__demo.moveTo(900, 500, 10));
  },
  steps: [
    { id: 'intro', chapter: 'Material Balance Studio', chapterSub: 'An oil rim under a gas cap',
      say: 'A second kind of reservoir: an oil rim under a gas cap, with water at its edge. This is an Ekene scenario made for the series. The engine generated its eight years of history from a tank of known size, so we know the answer. The oil is saturated at discovery: the initial pressure and the bubble point are both three thousand two hundred psia.',
      sub: 'A second kind of reservoir: an oil rim under a gas cap, with water at its edge. This is an Ekene scenario made for the series. The engine generated its eight years of history from a tank of known size, so we know the answer. The oil is saturated at discovery: the initial pressure and the bubble point are both 3,200 psia.',
      do: async (d) => {
        await expectText(d, t(d, 'mbal-case-summary'), /Initial P\s*3,200 psia[\s\S]*Bubble point\s*3,200 psia[\s\S]*Data rows\s*17/, 'case summary');
        await d.highlight(t(d, 'mbal-case-summary'));
        await d.sleep(3000);
        await d.unhighlight();
        const table = t(d, 'mbal-data-table');
        await table.evaluate((e) => e.scrollIntoView({ behavior: 'smooth', block: 'center' }));
        await d.sleep(1500);
      } },
    { id: 'gascap', chapter: 'The gas cap and the aquifer', chapterSub: 'What the model is told',
      say: 'Two things go into the model. The gas cap ratio m, the gas cap\'s reservoir volume over the oil\'s, is nought point four five, from the gas and oil columns on the logs. And the aquifer is Carter-Tracy: an edge aquifer over one hundred and eighty degrees, one hundred and fifty millidarcies, six times the radius of the reservoir.',
      sub: 'Two things go into the model. The gas cap ratio m, the gas cap\'s reservoir volume over the oil\'s, is 0.45, from the gas and oil columns on the logs. And the aquifer is Carter-Tracy: an edge aquifer over 180 degrees, 150 mD, six times the radius of the reservoir.',
      do: async (d) => {
        await d.click(tab(d, 'PVT'));
        await t(d, 'mbal-pvt-cf').waitFor({ timeout: 60000 });
        await d.sleep(1000);
        const m = d.page.locator('#gasCapM');
        await m.scrollIntoViewIfNeeded();
        await d.highlight(m.locator('xpath=ancestor::div[contains(@class,"border-t")][1]'));
        await d.sleep(3500);
        await d.unhighlight();
        await d.click(tab(d, 'Aquifer'));
        await d.sleep(1500);
        const k = t(d, 'mbal-aq-k');
        await k.scrollIntoViewIfNeeded();
        await d.highlight(k.locator('xpath=ancestor::div[contains(@class,"grid")][1]'));
        await d.sleep(4000);
        await d.unhighlight();
      } },
    { id: 'run', chapter: 'The run', chapterSub: 'Three drives at once',
      say: 'Run it. Eighteen million stock tank barrels of oil in place, at an r squared of one on sixteen surveys: the size the scenario was built with. The drive indices share the work three ways. At the last survey the gas cap supplies nought point three nine eight of the voidage, the water nought point two nine nine, and the oil and its gas nought point two eight four.',
      sub: 'Run it. 18 million stock tank barrels of oil in place, at an r² of one on sixteen surveys: the size the scenario was built with. The drive indices share the work three ways. At the last survey the gas cap supplies 0.398 of the voidage, the water 0.299, and the oil and its gas 0.284.',
      do: async (d) => {
        await runMbal(d, { onCamera: true });
        const card = t(d, 'mbal-result-card');
        await expectText(d, card, /OOIP\s*18\.00 MMSTB[\s\S]*Regression r2\s*1\.000000\s*16 points in the fit/, 'gas cap run');
        await d.highlight(card.locator('div.grid').first());
        await d.sleep(2500);
        await d.unhighlight();
        await expectText(d, card, /Depletion \(DDI\)\s*0\.284[\s\S]*Gas cap \(GDI\)\s*0\.398[\s\S]*Water drive \(WDI\)\s*0\.299/, 'drive indices');
        const idx = card.getByText('Depletion (DDI)').locator('xpath=ancestor::div[contains(@class,"grid")][1]');
        await idx.evaluate((e) => e.scrollIntoView({ behavior: 'smooth', block: 'center' }));
        await d.sleep(800);
        await d.highlight(idx);
        await d.sleep(4000);
        await d.unhighlight();
      } },
    { id: 'campbell', chapter: 'The signature of water', chapterSub: 'Campbell and the influx',
      say: 'Leave the aquifer out of the arithmetic and the Campbell plot climbs: each survey implies a bigger tank than the one before, because water is supplying energy the closed tank does not have. The influx plot shows that water arriving, faster as the pressure falls.',
      do: async (d) => {
        await d.click(tab(d, 'Plots'));
        const c = await showPlot(d, 'campbell');
        await d.highlight(c);
        await d.sleep(4000);
        await d.unhighlight();
        const w = await showPlot(d, 'influx');
        await d.highlight(w);
        await d.sleep(3500);
        await d.unhighlight();
      } },
    { id: 'hm', chapter: 'A second opinion', chapterSub: 'Pressure history match',
      say: 'The pressure history match works the other way: it simulates the pressure the tank would have had, and adjusts the oil in place and the aquifer radius until the two agree. Eighteen point zero six million barrels, within a third of a percent of the regression, with the pressures matched to a tenth of a psi.',
      sub: 'The pressure history match works the other way: it simulates the pressure the tank would have had, and adjusts the oil in place and the aquifer radius until the two agree. 18.06 million barrels, within a third of a percent of the regression, with the pressures matched to a tenth of a psi.',
      do: async (d) => {
        await d.click(tab(d, 'Run'));
        await d.sleep(1000);
        await d.click(seg(d, 'History match'));
        await d.sleep(1500);
        await d.click(d.page.getByRole('button', { name: /Run history match/ }));
        await d.waitText('mbal-hm-status-line', /Converged/, { timeout: 120000 });
        await d.sleep(1200);
        await expectText(d, t(d, 'mbal-hm-matched'), /STOIIP N \(MMSTB\)\s*18\.003\s*18\.064/, 'matched N');
        const tbl = t(d, 'mbal-hm-matched').locator('xpath=ancestor::table[1]');
        await tbl.evaluate((e) => e.scrollIntoView({ behavior: 'smooth', block: 'center' }));
        await d.sleep(800);
        await d.highlight(tbl);
        await d.sleep(3500);
        await d.unhighlight();
      } },
    { id: 'contacts', chapter: 'Moving contacts', chapterSub: 'Influx up, gas cap down',
      say: 'Where did the water and the gas go? The Contacts tab spreads the net influx over the oil-water contact area, and the gas cap expansion over the gas-oil contact area. At discovery the gas-oil contact was at four thousand nine hundred and fifty feet, and the oil-water contact at five thousand and sixty: a hundred and ten feet of oil.',
      sub: 'Where did the water and the gas go? The Contacts tab spreads the net influx over the oil-water contact area, and the gas cap expansion over the gas-oil contact area. At discovery the gas-oil contact was at 4,950 ft, and the oil-water contact at 5,060 ft: 110 ft of oil.',
      do: async (d) => {
        await d.click(tab(d, 'Contacts'));
        await t(d, 'mbal-contacts-anim').waitFor({ timeout: 60000 });
        await d.sleep(1000);
        await d.highlight(t(d, 'mbal-contacts-initialGocFt').locator('xpath=ancestor::div[contains(@class,"space-y-3")][1]'));
        await d.sleep(3500);
        await d.unhighlight();
        const anim = t(d, 'mbal-contacts-anim');
        await anim.evaluate((e) => e.scrollIntoView({ behavior: 'smooth', block: 'start' }));
        await d.sleep(1200);
        await d.click('mbal-contacts-anim-reset');
        await d.sleep(800);
      } },
    { id: 'play', chapter: 'Contacts through time', chapterSub: 'Eight years in eleven seconds',
      say: 'Press play. As the field produces, water sweeps up from below and gas expands down from above, and the oil column between them thins.',
      do: async (d) => {
        await d.click('mbal-contacts-anim-play');
        await d.waitText('mbal-contacts-anim-play', /Play/, { timeout: 30000 });
      },
      tail: 0.5 },
    { id: 'result',
      say: 'By January twenty twenty-five, the oil-water contact has risen by twenty five point four feet and the gas-oil contact has come down by twenty five point six, leaving fifty nine feet of oil. Wells completed near either contact would see water or gas first, and this is where to look.',
      sub: 'By January 2025, the oil-water contact has risen by 25.4 ft and the gas-oil contact has come down by 25.6, leaving 59.0 ft of oil. Wells completed near either contact would see water or gas first, and this is where to look.',
      do: async (d) => {
        await expectText(d, 'mbal-contacts-anim-readout', /2025-01[\s\S]*OWC risen by\s*25\.4 ft[\s\S]*GOC lowered by\s*25\.6 ft[\s\S]*Oil column\s*59\.0 ft/, 'final contacts');
        await d.highlight(t(d, 'mbal-contacts-anim-readout'));
        await d.sleep(4000);
        await d.unhighlight();
      } },
    { id: 'next', chapter: 'Gas cap and aquifer', chapterSub: 'Three drives, two contacts, one tank',
      say: 'Three drives, one tank, and contacts you can watch move. Next, three more years of data arrive for Ekene itself, and the material balance meets the volumetric booking.',
      do: async (d) => { await d.sleep(2500); } },
  ],
};
